import express from 'express';
import cors from 'cors';
import dotenv from 'dotenv';
import codebaseRoutes from './routes/codebaseRoutes.js';

dotenv.config();

const app = express();
app.use(cors());
app.use(express.json());

app.use('/api/codebase', codebaseRoutes);

app.get('/health', (req, res) => {
  res.status(200).json({ status: 'ok', service: 'Express Gateway' });
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => {
  console.log(`Express Gateway server running on port ${PORT}`);
});

import axios from "axios";
import fs from "fs";
import { getDirectoryTree } from "../utils/fileScanner.js";

const PYTHON_SERVICE =
  process.env.PYTHON_RAG_SERVICE_URL || "http://localhost:8000";

// GET /api/codebase/tree?repoPath=D:\path\to\repo
export const getFileTree = async (req, res) => {
  try {
    const { repoPath } = req.query;
    if (!repoPath || !fs.existsSync(repoPath)) {
      return res
        .status(400)
        .json({ success: false, message: "Invalid repository path" });
    }

    const tree = getDirectoryTree(repoPath);
    res.status(200).json({ success: true, data: tree });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
};

// GET /api/codebase/file-content?filePath=...
export const getFileContent = async (req, res) => {
  try {
    const { filePath } = req.query;
    if (!filePath || !fs.existsSync(filePath)) {
      return res
        .status(400)
        .json({ success: false, message: "File not found" });
    }

    const content = fs.readFileSync(filePath, "utf-8");
    res.status(200).json({ success: true, data: { filePath, content } });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
};

// POST /api/codebase/index
export const indexRepository = async (req, res) => {
  try {
    const { projectId, repoPath } = req.body;

    if (!projectId || !repoPath) {
      return res.status(400).json({
        success: false,
        message: "projectId and repoPath are required",
      });
    }

    const response = await axios.post(
      `${PYTHON_SERVICE}/index-repo`,
      {
        project_id: projectId,
        repo_path: repoPath,
      },
      {
        timeout: 300000, // Increased timeout to 5 minutes (300,000ms)
      },
    );

res.status(200).json(response.data);
  } catch (error) {
    res.status(error.response?.status || 502).json({
      success: false,
      message: error.response?.data?.detail || error.message,
    });
  }
};

// POST /api/codebase/query
export const queryCodebase = async (req, res) => {
  try {
    const { projectId, query, model } = req.body;

    const response = await axios.post(`${PYTHON_SERVICE}/query-codebase`, {
      project_id: projectId,
      query,
      model: model || "qwen2.5-coder:7b",
    });

res.status(200).json(response.data);
  } catch (error) {
    res.status(500).json({
      success: false,
      message: error.response?.data?.detail || error.message,
    });
  }
};

// POST /api/codebase/refactor
export const refactorCode = async (req, res) => {
  try {
    const { codeSnippet, instruction, filePath, model } = req.body;

    if (!codeSnippet || !instruction) {
      return res.status(400).json({
        success: false,
        message: "Missing code snippet or instruction",
      });
    }

const response = await axios.post(`${PYTHON_SERVICE}/refactor-code`, {
      code_snippet: codeSnippet,
      instruction,
      file_path: filePath || "snippet.js",
      model: model || "qwen2.5-coder:7b",
    });

    res.status(200).json(response.data);
  } catch (error) {
    res.status(500).json({
      success: false,
      message: error.response?.data?.detail || error.message,
    });
  }
};

import express from 'express';
import { 
  getFileTree, 
  getFileContent, 
  indexRepository, 
  queryCodebase,
  refactorCode 
} from '../controllers/codebaseController.js';

const router = express.Router();

router.get('/tree', getFileTree);
router.get('/file-content', getFileContent);
router.post('/index', indexRepository);
router.post('/query', queryCodebase);
router.post('/refactor', refactorCode);

export default router;

const IGNORED_DIRS = new Set(['.git', 'node_modules', 'dist', 'build', 'venv', '__pycache__', '.vscode']);

export const getDirectoryTree = (dirPath) => {
  const stats = fs.statSync(dirPath);

  if (!stats.isDirectory()) {
    return {
      name: path.basename(dirPath),
      path: dirPath,
      type: 'file'
    };
  }

  const name = path.basename(dirPath);
  if (IGNORED_DIRS.has(name)) return null;

  const children = fs.readdirSync(dirPath)
    .map(child => getDirectoryTree(path.join(dirPath, child)))
    .filter(Boolean);

return {
    name,
    path: dirPath,
    type: 'directory',
    children
  };
};
